# NX journal generated by Codex for BiaoJiXian bottom shallow groove test
import os
import NXOpen


def main():
    session = NXOpen.Session.GetSession()
    lw = session.ListingWindow
    lw.Open()
    part_path = r"C:\Users\Administrator\Desktop\标记线测试-xt_x_t.prt"
    dll_path = r"D:\UG智辉钣金插件\application\BiaoJIXIan.dll"
    log_path = r"D:\UG智辉钣金插件\logs\BiaoJIXIan_debug.log"
    lw.WriteLine("Codex BiaoJiXian autotest opening: " + part_path)
    base_part, load_status = session.Parts.OpenActiveDisplay(part_path, NXOpen.DisplayPartOption.AllowAdditional)
    try:
        load_status.Dispose()
    except Exception:
        pass
    os.environ["BIAOJIXIAN_AUTOTEST_BOTTOM"] = "1"
    lw.WriteLine("Codex BiaoJiXian autotest executing: " + dll_path)
    args = ["autotest_bottom"]
    session.ExecuteWithStringArguments(dll_path, "ufusr", args)
    lw.WriteLine("Codex BiaoJiXian autotest complete. Log: " + log_path)
    try:
        session.Parts.Work.Save(NXOpen.BasePart.SaveComponents.TrueValue, NXOpen.BasePart.CloseAfterSave.FalseValue)
    except Exception as ex:
        lw.WriteLine("Save skipped/failed: " + str(ex))

if __name__ == "__main__":
    main()
